    mobiusQ g₁ (mobiusQ g₂ q) = mobiusQ (g₁ * g₂) q

theorem measure_le_of_forall_exists_smul_mem [MeasurableSpace X] {μ : Measure X} [Countable G]
    [SMulInvariantMeasure G X μ] [MeasurableConstSMul G X] {F E : Set X}
    (hF : IsFundamentalDomain G F μ) (hE : ∀ x : X, ∃ g : G, g • x ∈ E) : μ F ≤ μ E

theorem smul_eq_self_of_coe_eq_pm_one {g : SL(2, ℂ)}
    (h : (g : Matrix (Fin 2) (Fin 2) ℂ) = 1 ∨ (g : Matrix (Fin 2) (Fin 2) ℂ) = -1) (q : H3) :
    g • q = q

theorem hvol_above_graph {D : Set (ℝ × ℝ)} (hD : MeasurableSet D) {g : ℝ × ℝ → ℝ}
    (hgm : Measurable g) (hgpos : ∀ z ∈ D, 0 < g z) :
    hvol {p : H3 | ((p.1 0, p.1 1) ∈ D) ∧ g (p.1 0, p.1 1) ≤ p.1 2}
      = ∫⁻ z in D, ENNReal.ofReal ((2 * g z ^ 2)⁻¹)

theorem halfBox_eq_above_graph :
